    public static byte[] SpectreDecrypt(byte[] bytes, int beginOffset, int count, bool isIndex, IAesVfsReader reader, object? customData = null)
    {
        if (bytes.Length < beginOffset + count)
            throw new IndexOutOfRangeException("beginOffset + count is larger than the length of bytes");
        if (count % 16 != 0)
            throw new ArgumentException("count must be a multiple of 16");
        if (reader.AesKey == null)
            throw new NullReferenceException("reader.AesKey");

        var ciphertext = bytes[beginOffset..];
        var plaintext = new byte[count];

        var key = reader.AesKey.Key;
        Span<uint> rk = stackalloc uint[RKLENGTH(AES_KEYBITS)];

        var nrounds = rijndaelSetupDecrypt(rk, key, AES_KEYBITS);

        for (var offset = 0; offset < count; offset += AES_BLOCKBYTES)
        {
            rijndaelDecrypt(rk, ciphertext.AsSpan()[offset..], plaintext.AsSpan()[offset..]);
        }

        return plaintext;
    }
